head.script:
scwin.onpageload = function() {
    //scwin.cnt++;
    var title = "wc1";
    var iconUrl = null;
    //        var src="gridView.xml";
    //        var src="trigger.xml";
    //        var src="/sample2/ckeditor.xml";
    //        var src = "/hyundai/tabControl_gridView_setGridStyle.xml";
    //        var src = "/WebSquare.xml";
    //        var src="/sample2/openPopup.xml";
    //        var src="/sample2/accordion1.xml";
    //        var src="/websquare/blank.xml";
    var src = "windowContainer_tabControl_spa_WESD-40_(WSQ-4177)_sub2.xml";
    var windowTitle = "wcTitle" + scwin.cnt;
    var windowId = "wcId" + scwin.cnt;
    var openAction = "selectWindow";
    var closeAction = "";
    var windowTooltip = "";
    var scope = $p.getRuntimeId("scwin");
    var arrNav = ["AAA", "BBB", "CCC", "DDD", "EEE", "FFF"];
    var arrWinHeaderHTML = [];
    arrWinHeaderHTML.push('<div class="w2group grp_pgtitle" data-menuNo="' + windowId + '"><div class="w2group ">');
    arrWinHeaderHTML.push('<div class="w2group leftbox">');
    arrWinHeaderHTML.push('<h1 style="color:#20255b;" class="w2textbox ">' + windowTitle + '(' + windowId + ')</h1>');
    arrWinHeaderHTML.push('</div>');
    arrWinHeaderHTML.push('<div class="w2group rightbox">');
    for (var i in arrNav) {
        if (i == 0) arrWinHeaderHTML.push('<span>' + arrNav[i] + '</span>');
        else arrWinHeaderHTML.push('<span> > ' + arrNav[i] + '</span>');
    }
    arrWinHeaderHTML.push('</div>');
    arrWinHeaderHTML.push('</div></div>');
    var windowHeaderHTML = arrWinHeaderHTML.join("");
    var options = "";
    var frameMode = "iframe";
    //windowContainer1.createWindow( title , iconUrl , src , windowTitle , windowId , openAction , closeAction , windowTooltip , windowHeaderHTML , options , frameMode )
    windowContainer1.createWindow(title, iconUrl, src);
    //        title="wc2";
    //        src="/sample2/ckeditor2.xml";
    //windowContainer1.createWindow( options.title, options.iconUrl, options.src );
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if (windowContainer1.windows.length > 4) {
        console.log("1234");
        windowContainer1.closeWindow(windowContainer1.windows[0].windowId);
    }
    scwin.cnt++;
    var title = "wc" + scwin.cnt;
    var iconUrl = null;
    var src = "/sample2/openPopup.xml";
    var windowTitle = "wcTitle" + scwin.cnt;
    var windowId = "wcId" + scwin.cnt;
    windowContainer1.createWindow(title, iconUrl, src, windowTitle, windowId, "selectWindow");
};
scwin.windowContainer1_onclosewindow = function(event) {
    /*
     * event : Object
     * event.src
     * event.id
     * event.title
     */
    console.log("event: ", event);
    var allData = $p.data.getAllDataCollection();
    for (var i = 0; i < allData.length; i++) {
        var dataID = allData[i];
        //debugger;
        if (dataID.slice(0, event.id.length + 1) === event.id + "_") {
            console.log("if1 true dataID: ", dataID);
        }
        if (dataID.match(new RegExp(event.id + "_"))[0]) {
            console.log("if2 true dataID: ", dataID);
        }
    }
};
scwin.trigger2_onclick = function(e) {
    $p.url("windowContainer_tabControl_spa_WESD-40_(WSQ-4177)_main.xml", {
        "spa": true
    });
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //var idx=0;
    scwin.cnt = 0;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
